  {motive :
    (a a_1 : Research.BinaryTreeReduction.Tree.{0} Real) →
      Research.BinaryTreeReduction.IsPerturbation bound a a_1 → Prop}
  (x y : Real) (error_le : LE.le.{0} (abs.{0} (HSub.hSub.{0, 0, 0} y x)) (HMul.hMul.{0, 0, 0} bound (abs.{0} x))),
  Research.BinaryTreeReduction.IsPerturbation.below ⋯

∀ {α : Type u_1} (left right : List.{u_1} (Research.BinaryTreeReduction.Tree.{u_1} α)),
  Eq.{u_1 + 1}
    (Research.BinaryTreeReduction.forestLeafMultiset.{u_1}
      (Research.BinaryTreeReduction.combineHalves.{u_1} left right))
    (HAdd.hAdd.{u_1, u_1, u_1} (Research.BinaryTreeReduction.forestLeafMultiset.{u_1} left)
