      (List.map.{u_1, u_1} Research.BinaryTreeReduction.Tree.leaf.{u_1} inputs))
    ↑inputs

declarations.body:
fun {α} forest =>
  have half := HDiv.hDiv.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} (List.length.{u_1} forest) 1) 2;
  Research.BinaryTreeReduction.combineHalves.{u_1} (List.take.{u_1} half forest) (List.drop.{u_1} half forest)

